function filter$hrbluongnv(p){
  this.constructor(p);
}
filter$hrbluongnv.prototype = new DirEvent();
filter$hrbluongnv.prototype.afterInit = function(){
  var p = this._dir, ev = this;
  var oPt = p.jObject('data_analysis_struct');
  oPt.find("[value='']").remove();
  p.options.pivotGroupAvailable = 1;

}

filter$hrbluongnv.prototype.commandActionClick = function (action, id, po) {
  var p = this._dir;
	var opt, m = new Memvars(), ma_maubc = 'hrbluongnv', mau_bc
  switch (action) {
    case 'mau_bc_cmd.add':
			/*
			var xm = m.val('ma_maubc', 'C', ma_maubc);
				p.request('hrmauluong01', '', xm, function(p, d){

