      });
		  */
      p.showFilter('dmmaubc', null, {_ma_maubc: ma_maubc});
		  //$.createDir(false, {controller: "dmmaubc", folder: "Filter", dirViewType: "Dialog", parent: p, _ma_maubc: ma_maubc});
	  	break;
		case 'mau_bc_cmd.edit':
			mau_bc = p.valForm('mau_bc');
			m.val('mau_bc', 'C', mau_bc);
			opt = $.extend({}, { controller: 'hrmauluong01', folder: "Grid", dirViewType: "Lookup", parent: p, memvars: m, lookupOk: false, _mau_bc: mau_bc, title: []}, {});
			$.createDir(false, opt);
