delete dmmaubc where ma_maubc = @ma_maubc and mau_bc = @mau_bc
select '' as val








declare @mau_bc varchar(33)
select @mau_bc = max(mau_bc) from dmmaubc where ma_maubc = @ma_maubc
if @mau_bc is null
	set @mau_bc = @ma_maubc
else begin
	declare @symbol char(1)
	select @symbol = upper(replace(rtrim(@mau_bc), @ma_maubc, ''))
	if @symbol = '' set @mau_bc = @ma_maubc + 'A'
	else set @mau_bc = @ma_maubc + char(ascii(@symbol) + 1)
end
select @mau_bc as mau_bc







exec ss_hrbluongnv @ky, @nam, @ma_bp, @ma_nv, @mau_bc, '@@lan', @@userId, @@admin



